def f(x):
    return x**3 + 4*x**2 - 3*x + 8

def f_derivative(x):
    return 3*x**2 + 8*x - 3

def newton_iteration(x):
    return x - f(x) / f_derivative(x)

# Find the smallest n where x_n and x_{n+1} round to the same value (4 decimals)
x = -5
for n in range(20):
    x_next = newton_iteration(x)
    if round(x, 4) == round(x_next, 4):
        print(n)
        break
    x = x_next
